package com.finsight.controller; import com.finsight.domain.ApplicationStatus; import com.finsight.repository.CreditApplicationRepository; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/dashboard") public class DashboardController {final CreditApplicationRepository repo;public DashboardController(CreditApplicationRepository r){repo=r;}@GetMapping("/summary")public Map<String,Long> summary(){return Map.of("total",repo.count(),"submitted",repo.countByStatus(ApplicationStatus.SUBMITTED),"riskAssessed",repo.countByStatus(ApplicationStatus.RISK_ASSESSED),"approved",repo.countByStatus(ApplicationStatus.APPROVED),"rejected",repo.countByStatus(ApplicationStatus.REJECTED));}}
